import json, sys
def iter_lines(path):
    with open(path) as f:
        for i, line in enumerate(f, 1):
            try: d = json.loads(line)
            except Exception: continue
            yield i, d
def tool_uses(path, t0=None, t1=None, names=None):
    for i, d in iter_lines(path):
        t = d.get('timestamp', '')
        if t0 and t < t0: continue
        if t1 and t > t1: continue
        if d.get('type') != 'assistant': continue
        msg = d.get('message', {})
        for c in msg.get('content', []) if isinstance(msg.get('content'), list) else []:
            if c.get('type') == 'tool_use' and (names is None or c.get('name') in names):
                yield i, t, c
if __name__ == '__main__':
    path, t0, t1 = sys.argv[1], sys.argv[2], sys.argv[3]
    names = sys.argv[4].split(',') if len(sys.argv) > 4 else None
    for i, t, c in tool_uses(path, t0, t1, names):
        inp = c.get('input', {})
        desc = inp.get('description') or inp.get('file_path') or inp.get('command', '')[:100]
        size = len(json.dumps(inp))
        print(i, t, c.get('name'), c.get('id'), repr(desc)[:140], size)
EOF
